import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import DashboardLayout from "../../layouts/DashboardLayout";
import {
  getAllcoursesWithlessons,
  createCourses,
  updateCourse,
  deleteCourse,
  createVideoLessons,
  updateLesson,
  deleteLesson,
} from "../../api";

export default function Courses() {
  const [courses, setCourses] = useState([]);
  const [showCourseModal, setShowCourseModal] = useState(false);
  const [showLessonModal, setShowLessonModal] = useState(false);
  const [videoPreview, setVideoPreview] = useState(null);

  const [editingCourse, setEditingCourse] = useState(null);
  const [editingLesson, setEditingLesson] = useState(null);

  const [courseForm, setCourseForm] = useState({ name: "", description: "" });
  const [lessonForm, setLessonForm] = useState({
    title: "",
    description: "",
    videoUrl: "",
    duration: "",
    courseIds: [],
  });

  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [limit] = useState(5);

  useEffect(() => {
    fetchCourses();
  }, [page]);

  const fetchCourses = async () => {
    const res = await getAllcoursesWithlessons(page, limit);
    setCourses(res.data.data);
    setTotalPages(res.data.totalPages);
  };

  const getEmbedUrl = (url) => {
    if (!url) return "";
    if (url.includes("watch?v=")) return url.replace("watch?v=", "embed/");
    if (url.includes("youtu.be/")) {
      const id = url.split("youtu.be/")[1];
      return `https://www.youtube.com/embed/${id}`;
    }
    return url;
  };

  const handleCourseSubmit = async () => {
    if (!courseForm.name) return alert("Name required");

    if (editingCourse) {
      await updateCourse(editingCourse.id, courseForm);
    } else {
      await createCourses(courseForm);
    }

    closeCourseModal();
    fetchCourses();
  };

  const handleLessonSubmit = async () => {
    if (!lessonForm.title || !lessonForm.videoUrl || !lessonForm.courseIds.length)
      return alert("All fields required");

    if (editingLesson) {
      await updateLesson(editingLesson.id, lessonForm);
    } else {
      await createVideoLessons(lessonForm);
    }

    closeLessonModal();
    fetchCourses();
  };

  const handleDeleteCourse = async (id) => {
    if (!window.confirm("Delete course?")) return;
    await deleteCourse(id);
    fetchCourses();
  };

  const handleDeleteLesson = async (id) => {
    if (!window.confirm("Delete lesson?")) return;
    await deleteLesson(id);
    fetchCourses();
  };

  const closeCourseModal = () => {
    setShowCourseModal(false);
    setEditingCourse(null);
    setCourseForm({ name: "", description: "" });
  };

  const closeLessonModal = () => {
    setShowLessonModal(false);
    setEditingLesson(null);
    setLessonForm({
      title: "",
      description: "",
      videoUrl: "",
      duration: "",
      courseIds: [],
    });
  };

  return (
    <DashboardLayout role="admin">
      <div className="p-6">
        <h2 className="text-2xl font-bold mb-6">Course Management</h2>

        <div className="flex gap-3 mb-6 flex-wrap">
          <button
            onClick={() => setShowCourseModal(true)}
            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded"
          >
            + Create Course
          </button>

          <button
            onClick={() => setShowLessonModal(true)}
            className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded"
          >
            + Add Lesson
          </button>
        </div>

        {/* RESPONSIVE WRAPPER */}
        <div className="overflow-x-auto border border-gray-300 rounded-lg">
          <table className="min-w-full border-collapse">
            <thead className="bg-gray-200">
              <tr>
                <th className="border border-gray-300 px-4 py-3 text-left">
                  Course
                </th>
                <th className="border border-gray-300 px-4 py-3 text-left">
                  Description
                </th>
                <th className="border border-gray-300 px-4 py-3 text-left">
                  Lessons
                </th>
                <th className="border border-gray-300 px-4 py-3 text-center">
                  Actions
                </th>
              </tr>
            </thead>

            <tbody>
              {courses.length > 0 ? (
                courses.map((course) => (
                  <tr key={course.id} className="hover:bg-gray-50">
                    <td className="border border-gray-300 px-4 py-3 font-medium align-top">
                      {course.name}
                    </td>

                    <td className="border border-gray-300 px-4 py-3 align-top">
                      {course.description}
                    </td>

                    {/* NESTED LESSON TABLE */}
                    <td className="border border-gray-300 px-3 py-3">
                      <div className="overflow-x-auto">
                        <table className="min-w-full border border-gray-300 border-collapse text-sm">
                          <thead className="bg-gray-100">
                            <tr>
                              <th className="border border-gray-300 px-3 py-2">
                                Lesson
                              </th>
                              <th className="border border-gray-300 px-3 py-2">
                                Description
                              </th>
                              <th className="border border-gray-300 px-3 py-2 text-center">
                                Video
                              </th>
                              <th className="border border-gray-300 px-3 py-2 text-center">
                                Duration
                              </th>
                              <th className="border border-gray-300 px-3 py-2 text-center">
                                Action
                              </th>
                            </tr>
                          </thead>

                          <tbody>
                            {course.lessons?.length ? (
                              course.lessons.map((lesson) => (
                                <tr key={lesson.id}>
                                  <td className="border border-gray-300 px-3 py-2">
                                    {lesson.title}
                                  </td>
                                  <td className="border border-gray-300 px-3 py-2">
                                    {lesson.description}
                                  </td>
                                  <td className="border border-gray-300 px-3 py-2 text-center">
                                    <button
                                      onClick={() =>
                                        setVideoPreview(lesson.videoUrl)
                                      }
                                      className="text-blue-600 underline"
                                    >
                                      Preview
                                    </button>
                                  </td>
                                  <td className="border border-gray-300 px-3 py-2 text-center">
                                    {lesson.duration}
                                  </td>
                                  <td className="border border-gray-300 px-3 py-2 text-center space-x-2">
                                    <button
                                      onClick={() => {
                                        setEditingLesson(lesson);
                                        setLessonForm({
                                          ...lesson,
                                          courseIds: [course.id],
                                        });
                                        setShowLessonModal(true);
                                      }}
                                      className="bg-yellow-500 hover:bg-yellow-600 text-white px-2 py-1 rounded text-xs"
                                    >
                                      Edit
                                    </button>

                                    <button
                                      onClick={() =>
                                        handleDeleteLesson(lesson.id)
                                      }
                                      className="bg-red-500 hover:bg-red-600 text-white px-2 py-1 rounded text-xs"
                                    >
                                      Delete
                                    </button>
                                  </td>
                                </tr>
                              ))
                            ) : (
                              <tr>
                                <td
                                  colSpan="5"
                                  className="text-center py-3 text-gray-500"
                                >
                                  No lessons available
                                </td>
                              </tr>
                            )}
                          </tbody>
                        </table>
                      </div>
                    </td>

                    <td className="border border-gray-300 px-4 py-3 text-center align-top space-y-2">
                      <button
                        onClick={() => {
                          setEditingCourse(course);
                          setCourseForm(course);
                          setShowCourseModal(true);
                        }}
                        className="bg-yellow-500 hover:bg-yellow-600 text-white px-3 py-1 rounded text-sm w-full"
                      >
                        Edit
                      </button>

                      <button
                        onClick={() => handleDeleteCourse(course.id)}
                        className="bg-red-500 hover:bg-red-600 text-white px-3 py-1 rounded text-sm w-full"
                      >
                        Delete
                      </button>

                      <button
                        onClick={() => {
                          setLessonForm({
                            ...lessonForm,
                            courseIds: [course.id],
                          });
                          setShowLessonModal(true);
                        }}
                        className="bg-green-600 hover:bg-green-700 text-white px-3 py-1 rounded text-sm w-full"
                      >
                        + Lesson
                      </button>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="4" className="text-center py-6 text-gray-500">
                    No courses found
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* PAGINATION */}
        <div className="flex justify-center gap-4 mt-6 flex-wrap">
          <button
            onClick={() => setPage((p) => Math.max(p - 1, 1))}
            disabled={page === 1}
            className="px-4 py-2 border rounded disabled:opacity-50"
          >
            Previous
          </button>

          <span className="px-4 py-2">
            Page {page} of {totalPages}
          </span>

          <button
            onClick={() => setPage((p) => Math.min(p + 1, totalPages))}
            disabled={page === totalPages}
            className="px-4 py-2 border rounded disabled:opacity-50"
          >
            Next
          </button>
        </div>

        {/* VIDEO MODAL */}
        {videoPreview && (
          <Modal title="Video Preview" onClose={() => setVideoPreview(null)}>
            {videoPreview.includes(".mp4") ? (
              <video controls width="100%">
                <source src={videoPreview} type="video/mp4" />
              </video>
            ) : (
              <iframe
                width="100%"
                height="350"
                src={getEmbedUrl(videoPreview)}
                allowFullScreen
                title="Video"
              />
            )}
          </Modal>
        )}
      </div>
    </DashboardLayout>
  );
}

function Modal({ title, children, onClose }) {
  return createPortal(
    <div
      onClick={onClose}
      className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-50"
    >
      <div
        onClick={(e) => e.stopPropagation()}
        className="bg-white w-[520px] max-w-[95%] p-6 rounded-lg"
      >
        <h3 className="mb-4 font-bold text-lg">{title}</h3>
        {children}
      </div>
    </div>,
    document.body
  );
}
